content.css:
.strategic-sunburst-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  --ss-panel-bg: #ffffff;
  --ss-panel-border: #e0e0e0;
  --ss-panel-accent: #E8612A;
  --ss-panel-text: #333333;
}
.strategic-sunburst-root svg {
  shape-rendering: geometricPrecision;
}
/* ── Arcs ── */
.ss-arc {
  cursor: pointer;
  stroke: #fff;
  stroke-width: 1;
  transition: opacity 0.2s ease;
}
.ss-arc:hover {
  filter: brightness(1.15);
  stroke-width: 1.5;
}
.ss-arc.dimmed {
  opacity: 0.2;
}
/* ── Labels ── */
.ss-label {
  fill: #fff;
  font-size: 10px;
  font-weight: 600;
  pointer-events: none;
  text-anchor: middle;
  paint-order: stroke;
  stroke: rgba(0, 0, 0, 0.5);
  stroke-width: 2.5px;
  stroke-linejoin: round;
}
/* ── Breadcrumb ── */
.ss-breadcrumb {
  display: flex;
  gap: 4px;
  padding: 6px 12px;
  border-bottom: 1px solid #e8e8e8;
  background: #fafbfc;
  flex-shrink: 0;
  min-height: 28px;
  align-items: center;
  flex-wrap: wrap;
}
.ss-breadcrumb-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 3px;
  font-size: 10px;
  color: #444;
  background: #eef0f3;
  cursor: pointer;
}
.ss-breadcrumb-item:hover {
  background: #dde0e5;
}
.ss-breadcrumb-sep {
  color: #bbb;
  font-size: 10px;
}
.ss-breadcrumb-value {
  font-weight: 700;
  color: #e8612a;
  margin-left: 4px;
}
/* ── Center label ── */
.ss-center-text {
  text-anchor: middle;
  fill: #333;
  pointer-events: none;
}
.ss-center-name {
  font-size: 14px;
  font-weight: 700;
}
.ss-center-value {
  font-size: 12px;
  fill: #666;
}
/* ── Landing page ── */
.ss-landing {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #888;
  font-size: 14px;
  text-align: center;
  padding: 24px;
  box-sizing: border-box;
}
/* ── Empty data message ── */
.ss-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #94a3b8;
  font-size: 12px;
  text-align: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
  letter-spacing: 0.2px;
}
/* ── Info button + popover ── */
.ss-info-bar {
  position: relative;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding: 2px 8px;
  flex-shrink: 0;
  min-height: 18px;
  z-index: 30;
}
.ss-info-btn {
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  color: #888;
  padding: 2px 6px;
  border-radius: 50%;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.ss-info-btn:hover {
  background: rgba(232, 97, 42, 0.12);
  color: var(--ss-panel-accent);
}
.ss-info-popover {
  position: absolute;
  top: 22px;
  right: 8px;
  width: 320px;
  max-width: 90%;
  background: #ffffff;
  border: 1px solid #d8d8d8;
  border-radius: 6px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.12);
  padding: 12px 14px;
  z-index: 40;
  font-size: 11.5px;
  color: #333;
  line-height: 1.45;
}
.ss-info-popover-title {
  font-weight: 700;
  font-size: 13px;
  margin-bottom: 6px;
  color: #222;
  border-bottom: 2px solid var(--ss-panel-accent);
  padding-bottom: 4px;
}
.ss-info-popover-body {
  margin-bottom: 8px;
}
.ss-info-popover-subtitle {
  font-weight: 600;
  color: #555;
  margin-top: 6px;
  margin-bottom: 4px;
}
.ss-info-popover-list {
  margin: 0;
  padding-left: 16px;
}
.ss-info-popover-list li {
  margin-bottom: 3px;
}
/* ── Content area (flex row: chart + secondary + insight) ── */
.ss-content-area {
  display: flex;
  flex-direction: row;
  flex: 1;
  min-height: 0;
}
.ss-chart-wrap {
  flex: 1;
  min-width: 0;
  min-height: 0;
  position: relative;
}
/* ── Secondary mini chart ── */
.ss-secondary-wrap {
  display: flex;
  flex-direction: column;
  width: 170px;
  min-width: 170px;
  flex: 0 0 170px;
  border-left: 1px solid var(--ss-panel-border);
  padding: 10px 10px 10px 12px;
  box-sizing: border-box;
  background: rgba(250, 251, 252, 0.6);
  overflow-y: auto;
  overflow-x: hidden;
}
.ss-secondary-title {
  font-weight: 700;
  font-size: 12px;
  color: #333;
  padding-bottom: 4px;
  border-bottom: 2px solid var(--ss-panel-accent);
}
.ss-secondary-subtitle {
  font-size: 10px;
  color: #888;
  margin-top: 2px;
  margin-bottom: 8px;
}
.ss-secondary-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ss-secondary-item {
  cursor: pointer;
  padding: 3px 2px;
  border-radius: 3px;
  transition: background 0.12s ease;
}
.ss-secondary-item:hover {
  background: rgba(232, 97, 42, 0.07);
}
.ss-secondary-name-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 10px;
  margin-bottom: 2px;
}
.ss-secondary-name {
  color: #333;
  font-weight: 500;
}
.ss-secondary-value {
  color: #666;
  font-weight: 600;
  font-size: 9.5px;
}
.ss-secondary-track {
  height: 6px;
  background: #ececec;
  border-radius: 3px;
  overflow: hidden;
}
.ss-secondary-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.25s ease;
}
/* ── Insight Panel (flex sidebar) ── */
.ss-insight-panel {
  display: none;
  width: 210px;
  min-width: 210px;
  flex: 0 0 210px;
  border-left: 1px solid var(--ss-panel-border);
  background: var(--ss-panel-bg);
  color: var(--ss-panel-text);
  padding: 12px;
  box-sizing: border-box;
  font-size: 11px;
  overflow-y: auto;
  overflow-x: hidden;
}
.ss-insight-title {
  font-weight: 700;
  font-size: 13px;
  color: var(--ss-panel-text);
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 2px solid var(--ss-panel-accent);
}
.ss-insight-collapse-row {
  display: flex;
  justify-content: flex-end;
  margin: -4px -4px 2px 0;
}
.ss-insight-collapse-btn {
  font-size: 11px;
  color: #888;
  cursor: pointer;
  user-select: none;
  padding: 2px 6px;
  border-radius: 3px;
  line-height: 1;
  transition: background 0.12s ease, color 0.12s ease;
}
.ss-insight-collapse-btn:hover {
  background: rgba(232, 97, 42, 0.12);
  color: var(--ss-panel-accent);
}
/* Thin strip shown when the panel is collapsed (click to re-expand) */
.ss-insight-strip {
  display: none;
  flex: 0 0 22px;
  width: 22px;
  min-width: 22px;
  border-left: 1px solid var(--ss-panel-border);
  background: rgba(255, 255, 255, 0);
  align-items: flex-start;
  justify-content: center;
  padding-top: 8px;
  cursor: pointer;
  transition: background 0.12s ease;
}
.ss-insight-strip:hover {
  background: rgba(232, 97, 42, 0.08);
}
.ss-insight-strip-arrow {
  font-size: 11px;
  color: #888;
  font-weight: 700;
  user-select: none;
}
.ss-insight-strip:hover .ss-insight-strip-arrow {
  color: var(--ss-panel-accent);
}
.ss-insight-row {
  display: flex;
  justify-content: space-between;
  padding: 3px 0;
}
.ss-insight-label {
  color: #666;
}
.ss-insight-value {
  font-weight: 600;
  color: var(--ss-panel-text);
}
.ss-insight-dist {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--ss-panel-border);
}
.ss-insight-dist-title {
  font-weight: 600;
  color: var(--ss-panel-text);
  margin-bottom: 6px;
}
.ss-insight-dist-item {
  margin-bottom: 4px;
}
.ss-insight-dist-name {
  font-size: 10px;
  color: #666;
  margin-bottom: 1px;
}
.ss-insight-dist-track {
  height: 8px;
  background: #e0e0e0;
  border-radius: 4px;
  overflow: hidden;
}
.ss-insight-dist-fill {
  height: 100%;
  background: linear-gradient(90deg, #5b9bd5, var(--ss-panel-accent));
  border-radius: 4px;
}
/* ── Smart Insights callouts ── */
.ss-smart-insights {
  margin-top: 12px;
  padding-top: 8px;
  border-top: 1px solid var(--ss-panel-border);
}
.ss-callout {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 8px;
  margin-top: 6px;
  font-size: 10.5px;
  line-height: 1.35;
  border-radius: 4px;
  border-left: 3px solid transparent;
}
.ss-callout-icon {
  flex-shrink: 0;
  font-weight: 700;
  font-size: 11px;
  width: 12px;
  text-align: center;
  line-height: 1.35;
}
.ss-callout-text {
  color: var(--ss-panel-text);
}
.ss-callout--lever {
  background: rgba(232, 97, 42, 0.08);
  border-left-color: var(--ss-panel-accent);
}
.ss-callout--lever .ss-callout-icon {
  color: var(--ss-panel-accent);
}
.ss-callout--warn {
  background: rgba(231, 76, 60, 0.08);
  border-left-color: #e74c3c;
}
.ss-callout--warn .ss-callout-icon {
  color: #e74c3c;
}
.ss-callout--info {
  background: rgba(127, 140, 141, 0.1);
  border-left-color: #95a5a6;
}
.ss-callout--info .ss-callout-icon {
  color: #7f8c8d;
}
/* ── License Badge & Watermark ── */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
